// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

// DataTables
$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${urlThis}/tabel`,
            type: 'POST',
            data: function (d) { d.filter_tipe = $('#filter_tipe').val(); }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => simpan() },
            {
                text: 'Reload',
                action: function (e, dt, node, config) {
                    dt.search('').draw();
                    $('#filter_tipe').val('').trigger('change');
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 10], className: 'dt-body-center' },
            { targets: 6, className: 'dt-body-right' },
            { targets: [4, 5, 6, 10], orderable: false },
            { targets: [8, 9], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data) } }
        ]
    });

    // Custom dropdown filter
    $('#tabelData_filter.dataTables_filter').append($('#filter_tipe'));
    $(document).on('change', '#filter_tipe', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    // Reset Modal
    $modalDiv
        .on('shown.bs.modal', function () { formCek.resetInitial(); })
        .on('hidden.bs.modal', function () { CirebonwebForm.FormReset(this); });
});

// Form Submit (Insert/Update)
function simpan(id) {
    let $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${urlThis}/simpan`;

    // Tentukan URL POST: Simpan atau Update
    if (id > 0) {
        CirebonwebForm.FormFetch(`${urlThis}/getid`, { id }, 'POST', {})
            .done(function (response) {
                if (response.success) {
                    $modalTitle.text('Edit Data');
                    $btnSubmit.text('Update');

                    // Isi form
                    $formData.find('#id').val(response.data.id);
                    $formData.find('#konsumen_tipe_id').val(response.data.konsumen_tipe_id);
                    $formData.find('#nama').val(response.data.nama);
                    $formData.find('#perusahaan').val(response.data.perusahaan);
                    $formData.find('#alamat').val(response.data.alamat);
                    $formData.find('#kota').val(response.data.kota);
                    $formData.find('#whatsapp').val(response.data.whatsapp);
                    $formData.find('#email').val(response.data.email);
                    $modalDiv.modal('show');
                }
            })
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $modalDiv.modal('show');
    }

    // Form Validasi
    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            konsumen_tipe_id: { required: true },
            nama: { required: true, minlength: 3, maxlength: 30 },
            perusahaan: { required: false, minlength: 3, maxlength: 30 },
            alamat: { required: false, minlength: 5, maxlength: 100 },
            kota: { required: true, minlength: 5, maxlength: 20 },
            whatsapp: { required: false, minlength: 5, maxlength: 20 },
            // telegram_id: { required: false, digits: true, minlength: 5, maxlength: 20 },
            email: { required: false, customEmail: true }
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;
            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    if (!formCek.isChanged()) return false;
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Submit') }
            })
                .done(function (response) {
                    if (!response.success) return;
                    $modalDiv.modal('hide');
                    Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                        .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
                });
            return false; // Mencegah submit native
        }
    })
    )
}

// Form Submit (Delete)
function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${urlThis}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}
